%% coding: utf-8
-module(main).
-export([main/1]).

main(_) ->
    io:setopts(standard_io, [{encoding, unicode}]),
    List = [38, 27, 43, 3, 9, 82, 10],
    Sorted = merge_sort(List),
    io:format("Sorted list: ~p~n", [Sorted]).

merge_sort([]) -> [];
merge_sort([X]) -> [X];
merge_sort(List) ->
    {Left, Right} = split(List, length(List) div 2, []),
    merge(merge_sort(Left), merge_sort(Right)).

split(List, 0, Acc) -> {lists:reverse(Acc), List};
split([Head | Tail], N, Acc) -> split(Tail, N - 1, [Head | Acc]).

merge([], Right) -> Right;
merge(Left, []) -> Left;
merge([L | Ls], [R | Rs]) when L =< R -> [L | merge(Ls, [R | Rs])];
merge([L | Ls], [R | Rs]) -> [R | merge([L | Ls], Rs)].

%% coding: utf-8
-module(main).
-export([main/1]).

main(_) ->
    io:setopts(standard_io, [{encoding, unicode}]),
    %% اللاعب يختار حجراً، والخصم ورقة، فالنتيجة خسارة
    io:format("~ts~n", [result(rock, paper)]).

result(rock, paper) -> "You lose: paper covers rock";
result(paper, rock) -> "You win: paper covers rock";
result(scissors, paper) -> "You win: scissors cut paper";
result(paper, scissors) -> "You lose: scissors cut paper";
result(rock, scissors) -> "You win: rock crushes scissors";
result(scissors, rock) -> "You lose: rock crushes scissors";
result(_, _) -> "Tie".
